WITH d AS (
  SELECT geom FROM fr_departements WHERE nom = 'Landes'
), b AS (
  SELECT ST_Buffer(ST_Centroid(geom), 25000) AS geom FROM d
), diff AS (
  SELECT ST_Difference(d.geom, b.geom) AS geom FROM d, b
)
SELECT ST_Area(geom) / 1000000 AS area_km2 FROM diff

WITH d AS (
  SELECT geom FROM fr_departements WHERE nom IN ('Landes', 'Pyrénées-Orientales')
), u AS (
  SELECT ST_Union_Agg(geom) AS geom FROM d
)
SELECT ST_Area(geom) / 1000000 AS area_km2 FROM u

WITH d AS (
  SELECT geom FROM fr_departements WHERE nom IN ('Ardennes', 'Meurthe-et-Moselle', 'Tarn-et-Garonne')
), hull AS (
  SELECT ST_ConvexHull(ST_Union_Agg(geom)) AS geom FROM d
)
SELECT ST_Area(geom) / 1000000 AS area_km2 FROM hull

WITH d AS (
  SELECT geom FROM fr_departements WHERE nom = 'Ardennes'
), b AS (
  SELECT ST_Buffer(ST_Centroid(geom), 20000) AS geom FROM d
)
SELECT ST_Area(geom) / 1000000 AS area_km2 FROM b
